function expertPortraitId(member   
                                                                                                
 )                     {
  for (const id of [member.sourceExpertId, member.expertId]) {
    if (EXPERT_PORTRAITS.some(item => item.expertId === id)) return `expert-${id}`
  }
  // Old teams may only retain a nickname with a task suffix. Do not match arbitrary substrings.
  const names = [member.name, member.displayName].filter((name)                 => typeof name === 'string')
  const found = EXPERT_PORTRAITS.find(item => names.some(raw => {
    const name = raw.trim()
    return name === item.expertId || item.aliases.some(alias => name === alias
      || (name.startsWith(alias) && /^[·・|｜（(\s—:：]/u.test(name.slice(alias.length))))
  }))
  return found ? `expert-${found.expertId}` : undefined
}

/** This allowlist also fences static assets and pack-provided asset references. */
const EXPERT_PORTRAIT_IDS                    = EXPERT_PORTRAITS.map(item => `expert-${item.expertId}`)
function isExpertPortrait(id        )          { return EXPERT_PORTRAIT_IDS.includes(id) }
function expertPortraitUrl(id        , avatar = false)         {
  const version = id === 'coordinator' ? 'coordinator-young-20261007' : 'domain-portraits-20261007'
  return `/plugins/dsh-expert-library/review/portraits/${id}${avatar ? '-avatar' : ''}.webp?v=${version}`
}

/** Additive shared cast: retain the original six portraits and named identities. */
const SHARED_PORTRAIT_ROLES = ['coordinator', 'finance', 'policy', 'market', 'engineer', 'reviewer']         
                                                                     
const PORTRAIT_POSES                                                                    = [
  {id:'pose-coordinator-discuss',role:'coordinator',label:'侧身讲解'},
  {id:'pose-coordinator-listen',role:'coordinator',label:'倾听讨论'},
  {id:'pose-finance-laptop',role:'finance',label:'抱电脑交流'},
  {id:'pose-finance-think',role:'finance',label:'托腮推演'},
  {id:'pose-policy-read',role:'policy',label:'侧身翻阅'},
  {id:'pose-policy-explain',role:'policy',label:'手势说明'},
  {id:'pose-market-survey',role:'market',label:'观察记录'},
  {id:'pose-market-map',role:'market',label:'展开地图'},
  {id:'pose-engineer-type',role:'engineer',label:'操作电脑'},
  {id:'pose-engineer-sketch',role:'engineer',label:'侧身构思'},
  {id:'pose-reviewer-check',role:'reviewer',label:'低头核对'},
  {id:'pose-reviewer-discuss',role:'reviewer',label:'开放评议'},
]
function hasPortraitAvatar(id       )         {
  return isExpertPortrait(id)||PORTRAIT_POSES.some(p=>p.id===id)
}
function isRegisteredPortrait(id       )         {
  return SHARED_PORTRAIT_ROLES.some(role=>role===id)||hasPortraitAvatar(id)
}
function portraitHash(key       )        {
  let hash=2166136261
  for(const ch of key)hash=Math.imul(hash^ch.charCodeAt(0),16777619)
  return hash>>>0
}
function sharedPortraitRole(key       ,role       )                    {
  if(/队长|统筹|组织|协调|coordin|captain|lead/i.test(role))return 'coordinator'
  if(/评审|审核|审查|风控|合规|质控|review|critic|security|quality|\bqa\b/i.test(role))return 'reviewer'
  if(/工程|开发|技术|设计|code|engineer|developer|design/i.test(role))return 'engineer'
  if(/政策|制度|公共|法律|policy|regulat|legal/i.test(role))return 'policy'
  if(/金融|银行|信贷|经营|财务|估值|收益|finance|bank|credit|valuation/i.test(role))return 'finance'
  if(/市场|城市|指数|租赁|数据|研究|分析|market|index|tier|stock|data|research|analyst/i.test(role))return 'market'
  return SHARED_PORTRAIT_ROLES[portraitHash(key)%SHARED_PORTRAIT_ROLES.length] 
}
/** Stable per identity, with two younger poses and the original person per role. */
function sharedPortraitId(key       ,role       ,preferredRole        )        {
  const category=SHARED_PORTRAIT_ROLES.find(r=>r===preferredRole)||sharedPortraitRole(key,role)
  const choices=[...PORTRAIT_POSES.filter(p=>p.role===category).map(p=>p.id),category]
  return choices[portraitHash(key)%choices.length] 
}
