function renderSettings(plan, team) {
  $('planContent').querySelector('.settingsGuide')?.remove()
  const box = element('section', undefined, 'settingsGuide')
  box.append(heading('本页操作与设置'))
  for (const [name, value, state] of [
    ['执行计划', plan.status === 'staged' && !team ? '核对后可在此页确认启动' : '本次执行版本已锁定', plan.status === 'staged' && !team ? '可确认' : '已锁定'],
    ['大纲方向', '候选方案就绪后，在“大纲”页选择；已确认版本保留记录', '待就绪可选'],
    ['专家、模型、研究方法与流程', last?.canEditPlan ? '在下方选择并保存，核对新版计划后确认执行。' : '执行配置已锁定；后续调整需回工作区修订计划。', last?.canEditPlan ? '可编辑' : '已锁定'],
  ]) {
    const row = element('div', undefined, 'settingRow'); const copy = element('div'); copy.append(element('strong',name),element('p',value)); row.append(copy,element('span',state,'settingState')); box.append(row)
  }
  renderPlanDropdowns(plan,box)
  $('planContent').prepend(box)
}
