  if (team.halted) root.append(problemNotice(team.haltReason || '团队已暂停，等待恢复。'))
  const teamKey=team.captainSessionId+':'+team.id
  if(activityViewTeam!==teamKey){activityViewTeam=teamKey;activityViewMode=window.innerWidth<=620?'list':'graph'}
  const toggle=element('div',undefined,'activityViewSwitch');toggle.setAttribute('aria-label','进展查看方式')
