  if(/DEEP_RESEARCH_SELECTION_INVALID/.test(code))return '研究流程或专家选择已失效。请重新选择并保存计划。'
  if(/PRESET_INPUT_FROZEN/.test(code))return '计划输入已冻结。请返回原工作区修改计划后重新确认。'
