// Pointer depth uses a damped spring; never follows touch or steals scrolling.
let springFrame=0, sx=0, sy=0, vx=0, vy=0, targetX=0, targetY=0
const scene = document.querySelector('.heroScene'), hero = document.querySelector('.studioHero')
function resetPaperSpring() {
  cancelAnimationFrame(springFrame); springFrame=0; sx=sy=vx=vy=targetX=targetY=0
  scene.style.setProperty('--paper-x','0px'); scene.style.setProperty('--paper-y','0px')
}
function springPaper() {
  springFrame=0
  if (!studioMovable()) {resetPaperSpring();return}
  vx=(vx+(targetX-sx)*.065)*.78;vy=(vy+(targetY-sy)*.065)*.78;sx+=vx;sy+=vy
  scene.style.setProperty('--paper-x',sx.toFixed(2)+'px');scene.style.setProperty('--paper-y',sy.toFixed(2)+'px')
  if (Math.abs(targetX-sx)+Math.abs(targetY-sy)+Math.abs(vx)+Math.abs(vy)>.06) springFrame=requestAnimationFrame(springPaper)
}
hero.addEventListener('pointermove',event=>{if(event.pointerType!=='mouse'||!studioMovable())return;const r=hero.getBoundingClientRect();targetX=((event.clientX-r.left)/r.width-.5)*12;targetY=((event.clientY-r.top)/r.height-.5)*8;if(!springFrame)springFrame=requestAnimationFrame(springPaper)},{passive:true})
hero.addEventListener('pointerleave',()=>{targetX=targetY=0;if(!springFrame&&studioMovable())springFrame=requestAnimationFrame(springPaper)})
$('motionToggle').addEventListener('click',resetPaperSpring)
onMotionChange(resetPaperSpring)
document.addEventListener('visibilitychange',()=>{if(document.hidden)resetPaperSpring()})
window.addEventListener('pagehide',()=>{resetPaperSpring();clearTimeout(receiptTimer)})

const disclosureStates = new Map()
document.addEventListener('click', event => {const summary=event.target.closest('summary');const details=summary?.parentElement;if(details?.dataset.disclosure)disclosureStates.set(details.dataset.disclosure,!details.open)})
function memberActivity(member,team) {
  const tasks=team?.tasks||[], owned=tasks.filter(t=>t.assignee===member.name||t.assignee===member.id), remaining=owned.filter(t=>t.status!=='completed')
  const running=remaining.find(t=>taskProgress(t).tone==='working')
  const blocked=remaining.find(t=>taskProgress(t).tone==='blocked')
  if(!remaining.length&&owned.length)return{key:'done',label:'已完成',rank:5,detail:'本轮任务已完成，文件可在研究成果中查看。'}
  if(team?.halted)return{key:'blocked',label:'已暂停',rank:1,detail:'团队已暂停，等待处理后恢复。'}
  if(blocked)return{key:'blocked',label:'需要处理',rank:1,detail:`受阻任务：${taskTitle(blocked)}`}
  if(running)return{key:'working',label:'工作中',rank:0,detail:`正在处理：${taskTitle(running)}`}
  const reviewing=remaining.find(t=>t.executionState==='awaiting_review'||reviewWaitCopy(t.waitReason));if(reviewing)return{key:'waiting',label:taskProgress(reviewing).label,rank:2,detail:reviewWaitCopy(reviewing.waitReason)?.message||'稿件已提交，等待评审确认。'}
  if(!owned.length)return{key:'idle',label:'暂无任务',rank:4,detail:'当前尚未分配任务，等待队长派发。'}
  const deps=t=>(t.dependencies||t.dependsOn||[]).filter(id=>tasks.find(x=>x.id===id)?.status!=='completed')
  const ready=remaining.find(t=>!deps(t).length)
  if(ready)return{key:'ready',label:'待接手',rank:2,detail:`前置已齐，等待启动：${taskTitle(ready)}`}
  const ids=[...new Set(remaining.flatMap(deps))]
  return{key:'waiting',label:'等待前置',rank:3,detail:`等待 ${taskNames(ids,tasks)} 完成后接手。`}
}
function renderCollaboration(team,plan) {
  const root=$('sceneExperts');root.replaceChildren()
  const fullTitle=team?.name || plan?.runtime?.teamName || plan?.preview?.expertSelection?.question || '专家研究计划'
  // Keep the full plan name in the overview; omit only workspace/version labels on the cover.
  $('heroResearchTitle').textContent=fullTitle.replace(/^(?:98wiki|99wiki)\s+/i,'').replace(/\s+v\d+(?:\.\d+)*(?:[（(][^）)]*[）)])?$/i,'')
  $('heroResearchTitle').title=fullTitle
  const order={working:0,ready:1,waiting:2,blocked:3,idle:4,done:5}
  const ranked=(team?.members||[]).map((member,index)=>({member,index,state:memberActivity(member,team)})).sort((a,b)=>order[a.state.key]-order[b.state.key]||a.index-b.index)
  const unfinished=ranked.filter(item=>!['done','idle'].includes(item.state.key))
  const people=(unfinished.length?unfinished:ranked).slice(0,3).map(item=>item.member)
  root.dataset.count=String(people.length||3)
  if(!people.length)people.push({name:'研究队长',role:'研究统筹',art:'team-lead'},{name:'研究专家',role:'证据研究',art:'researcher'},{name:'评审专家',role:'独立评审',art:'security-reviewer'})
  people.forEach((m,i)=>{const actor=element('div',undefined,'sceneExpert actor'+i);const img=element('img');setExpertPortrait(img,m);const status=team?memberActivity(m,team):{key:'waiting',label:'待计划确认'};actor.dataset.activity=status.key;actor.append(img,element('strong',expertPresentation(m).label),element('small',status.label));if(team){const owned=team.tasks.filter(t=>t.assignee===m.name||t.assignee===m.id);const target=owned.find(t=>taskProgress(t).tone==='working')||owned.find(t=>t.status!=='completed')||owned.at(-1);if(target){actor.setAttribute('role','button');actor.tabIndex=0;actor.setAttribute('aria-label',`查看${m.name}负责的任务`);actor.addEventListener('click',()=>focusResearchTask(target.id));actor.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();focusResearchTask(target.id)}})}}root.append(actor)})
  const active=team?.members?.filter(m=>memberActivity(m,team).key==='working').length||0
  document.querySelector('.collaborationScene').dataset.working=String(active>0)
  $('heroResearchSummary').textContent=team?`围绕当前课题持续协作 · ${active} 位专家工作中 · ${team.tasks.filter(t=>t.status==='completed').length}/${team.tasks.length} 项任务已完成`:'先核对研究路线与专家配置，确认后开始协作。'
  $('sceneStatus').textContent=team?`当前 ${active} 位工作中 · ${team.tasks.filter(t=>t.status==='completed').length}/${team.tasks.length} 项已交付`:'确认计划后，专家将按分工开始协作。'
}

